export function filterProducts(products, category = 'الكل', query = '') {
  const normalized = query.trim().toLocaleLowerCase('ar');
  return products.filter((product) => {
    const matchesCategory = category === 'الكل' || product.category === category;
    const searchable = `${product.name} ${product.category} ${product.maker}`.toLocaleLowerCase('ar');
    return matchesCategory && (!normalized || searchable.includes(normalized));
  });
}

export function calculateSubtotal(cart, products = PRODUCTS) {
  return Object.entries(cart).reduce((sum, [id, quantity]) => {
    const product = products.find((item) => item.id === id);
    return product ? sum + product.price * quantity : sum;
  }, 0);
}
